    private readonly PixelSelectionEngineOperations _smartSelection=new();
    public Settings prepare_pixel_source(Control owner)
    {
        long generation=owner.Get("_pixel_prepare_generation").AsInt64()+1;owner.Set("_pixel_prepare_generation",generation);var canvas=Canvas(owner);canvas.Set("pixel_source",default(Variant));_smartSelection.invalidate(canvas.Get("smart_selection").As<Node>());var document=Document(owner);var layer=main_layer(owner);if(layer==null||!_documents.can_edit(document,layer)){owner.Get("status").As<Label>().Text="Select an unlocked layer to select its pixels.";return new Settings();}var temporary=NewDocument();Assign(temporary.Get("live_materials").AsGodotArray(),document.Get("live_materials").AsGodotArray());temporary.Set("canvas_size",document.Get("canvas_size"));var isolated=_layers.copy_layer(layer);var world=_documents.world_transform(document,layer);isolated.Set("parent_id","");var half=layer.Get("dimensions").AsVector2()*.5f;isolated.Set("position",world*half-half);_layers.set_linear_basis(isolated,world);isolated.Set("blend",0);temporary.Get("layers").AsGodotArray().Add(isolated);var renderer=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_renderer.gd").New().As<Node>();owner.AddChild(renderer);_renderer.sync(renderer,temporary);return new Settings{["generation"]=generation,["document"]=document,["layer"]=layer,["world"]=world,["renderer"]=renderer};
    }
    public void complete_pixel_source(Control owner,Settings request,Image? pixels)
    {
        request["renderer"].As<Node>().QueueFree();var layer=request["layer"].As<Resource>();if(request["generation"].AsInt64()!=owner.Get("_pixel_prepare_generation").AsInt64()||request["document"].AsGodotObject()!=Document(owner)||main_layer(owner)!=layer||pixels==null)return;pixels.Convert(Image.Format.Rgba8);var canvas=Canvas(owner);canvas.Set("pixel_source",pixels);var area=request["world"].AsTransform2D()*new Rect2(Vector2.Zero,_layers.content_dimensions(layer));canvas.Set("pixel_domain",new Rect2I((Vector2I)area.Position.Floor(),(Vector2I)area.Size.Ceil()).Intersection(new Rect2I(Vector2I.Zero,Document(owner).Get("canvas_size").AsVector2I())));if(canvas.Get("edge_magnet").AsBool()||canvas.Get("pixel_mode").AsString()=="object")_canvas.prepare_smart_selection(canvas);owner.Get("status").As<Label>().Text="Paint selects · Erase subtracts · Fill selects connected colors · Ctrl+Z undoes · Copy / Delete / Extract";
    }
    public Settings prepare_pixel_action(Control owner,string action)
    {
        finish_pending(owner);var document=Document(owner);var canvas=Canvas(owner);var layer=main_layer(owner);var selection=canvas.Get("selection").As<Image>();if(layer==null||!_documents.can_edit(document,layer)||selection==null||canvas.Get("pixel_source").AsGodotObject()==null||!selection.GetUsedRect().HasArea())return new Settings();return new Settings{["document"]=document,["layer"]=layer,["version"]=owner.Get("_edit_version"),["action"]=action,["local_mask"]=action=="delete"&&layer.Get("live_paint").AsGodotArray().Count>0};
    }
    public void complete_pixel_action(Control owner,Settings request,Texture2D? localMask)
    {
        var document=Document(owner);var canvas=Canvas(owner);var layer=request["layer"].As<Resource>();if(request["document"].AsGodotObject()!=document||request["version"].AsInt64()!=owner.Get("_edit_version").AsInt64()||_documents.layer_for_id(document,layer.Get("id").AsString())!=layer)return;string action=request["action"].AsString();if(request["local_mask"].AsBool())
        {
            if(localMask==null)return;using var coverage=localMask.GetImage();Action(owner,()=>{_layers.erase_live_paint(layer,coverage);using var bitmap=layer.Get("texture").As<Texture2D>().GetImage();var bytes=bitmap.GetData();if(coverage.GetSize()!=bitmap.GetSize())coverage.Resize(bitmap.GetWidth(),bitmap.GetHeight(),Image.Interpolation.Bilinear);var masks=coverage.GetData();for(int i=3;i<bytes.Length;i+=4)bytes[i]=(byte)Mathf.RoundToInt(bytes[i]*(1-masks[i]/255.0));bitmap.SetData(bitmap.GetWidth(),bitmap.GetHeight(),false,Image.Format.Rgba8,bytes);layer.Set("texture",ImageTexture.CreateFromImage(bitmap));});FinishPixelAction(owner);return;
        }
        using var pixels=(Image)canvas.Get("pixel_source").As<Image>().Duplicate();using var extracted=Image.CreateEmpty(pixels.GetWidth(),pixels.GetHeight(),false,Image.Format.Rgba8);extracted.Fill(Colors.Transparent);var bounds=canvas.Get("pixel_selection_bounds").AsRect2();var area=new Rect2I((Vector2I)bounds.Position.Floor(),(Vector2I)bounds.Size.Ceil()).Intersection(new Rect2I(Vector2I.Zero,pixels.GetSize()));var sampler=new ImageCanvasSelectionOperations.SelectionSampler(canvas);for(int y=area.Position.Y;y<area.End.Y;y++)for(int x=area.Position.X;x<area.End.X;x++){float coverage=(float)sampler.Coverage(new Vector2(x+.5f,y+.5f));if(coverage<=0)continue;var original=pixels.GetPixel(x,y);var taken=original;taken.A*=coverage;extracted.SetPixel(x,y,taken);if(action!="copy")pixels.SetPixel(x,y,original.Lerp(Colors.Transparent,coverage));}var selectionLayer=basic_from_image(owner,extracted,"Selected pixels");
        Action(owner,()=>{if(action!="copy"){var transforms=new Settings();foreach(var value in _documents.children(document,layer.Get("id").AsString())){var child=value.As<Resource>();transforms[child.Get("id")]=_documents.world_transform(document,child);}var baked=basic_from_image(owner,pixels,layer.Get("label").AsString());var parent=_documents.layer_for_id(document,layer.Get("parent_id").AsString());var inverse=parent!=null?_documents.world_transform(document,parent).AffineInverse():Transform2D.Identity;layer.Set("kind","basic");layer.Set("dimensions",baked.Get("dimensions"));var half=baked.Get("dimensions").AsVector2()*.5f;layer.Set("position",inverse*(baked.Get("position").AsVector2()+half)-half);layer.Get("live_paint").AsGodotArray().Clear();layer.Set("rotation",0.0);layer.Set("opacity",1.0);layer.Set("texture",baked.Get("texture"));layer.Set("paint_base",baked.Get("paint_base"));layer.Set("mask",default(Variant));layer.Set("warp",default(Variant));layer.Get("effects").AsGodotArray().Clear();layer.Set("properties",baked.Get("properties"));_layers.set_linear_basis(layer,inverse);var newInverse=_documents.world_transform(document,layer).AffineInverse();foreach(var value in _documents.children(document,layer.Get("id").AsString())){var child=value.As<Resource>();var previous=transforms[child.Get("id")].AsTransform2D();half=child.Get("dimensions").AsVector2()*.5f;child.Set("position",newInverse*(previous*half)-half);_layers.set_linear_basis(child,newInverse*previous);}}
            if(action!="delete"){document.Get("layers").AsGodotArray().Add(selectionLayer);var selected=canvas.Get("selected").AsGodotArray();selected.Clear();selected.Add(selectionLayer.Get("id"));}document.Set("pixel_selection",default(Variant));document.Set("pixel_selection_owner","");document.Set("pixel_selection_reference",default(Variant));document.Set("pixel_selection_reference_world",Transform2D.Identity);});FinishPixelAction(owner);
    }
    private void FinishPixelAction(Control owner){var canvas=Canvas(owner);_canvas.clear_selection(canvas);canvas.Set("pixel_source",default(Variant));owner.Call("_set_tool","move");}
    public void commit_selection_bitmap(Control owner,Image bitmap)
    {
        var layer=main_layer(owner);if(layer==null)return;var document=Document(owner);Action(owner,()=>{document.Set("pixel_selection",ImageTexture.CreateFromImage(bitmap));document.Set("pixel_selection_owner",layer.Get("id"));document.Set("pixel_selection_reference",_layers.copy_layer(layer));document.Set("pixel_selection_reference_world",_documents.world_transform(document,layer));});_canvas.sync_pixel_selection(Canvas(owner));owner.Call("_refresh_context");
    }
    public void selection_to_mask(Control owner)
    {
        var canvas=Canvas(owner);if(canvas.Get("selection").AsGodotObject()==null){owner.Get("status").As<Label>().Text="Draw a pixel selection first (M / L), then choose Mask.";return;}var sampler=new ImageCanvasSelectionOperations.SelectionSampler(canvas);Action(owner,()=>{foreach(var id in canvas.Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(Document(owner),id.AsString());if(layer==null)continue;var size=((Vector2I)layer.Get("dimensions").AsVector2()).Max(Vector2I.One);using var mask=Image.CreateEmpty(size.X,size.Y,false,Image.Format.Rgba8);var transform=_documents.world_transform(Document(owner),layer);var projection=new ImageLayerProjection(layer);for(int y=0;y<size.Y;y++)for(int x=0;x<size.X;x++){float coverage=(float)sampler.Coverage(transform*projection.Project(new Vector2(x,y),new Vector2(-1,-1)));mask.SetPixel(x,y,new Color(coverage,coverage,coverage,1));}layer.Set("mask",ImageTexture.CreateFromImage(mask));}});_canvas.clear_selection(canvas);
    }
    public void invert_selection(Control owner)
    {
        var canvas=Canvas(owner);var selection=canvas.Get("selection").As<Image>();if(selection==null)return;using var result=current_selection_bitmap(owner);for(int y=0;y<result.GetHeight();y++)for(int x=0;x<result.GetWidth();x++){float coverage=1-result.GetPixel(x,y).A;result.SetPixel(x,y,new Color(1,1,1,coverage));}commit_selection_bitmap(owner,result);
    }
    public void smart_select(Control owner,string kind,Color reference,double threshold)
    {
        var canvas=Canvas(owner);var source=canvas.Get("pixel_source").As<Image>();if(source==null)return;var size=Document(owner).Get("canvas_size").AsVector2I();using var mask=Image.CreateEmpty(size.X,size.Y,false,Image.Format.Rgba8);mask.Fill(Colors.Transparent);for(int y=0;y<source.GetHeight();y++)for(int x=0;x<source.GetWidth();x++){var color=source.GetPixel(x,y);float luminance=.2126f*color.R+.7152f*color.G+.0722f*color.B;bool chosen=kind switch{"opaque"=>color.A>.001,"transparent"=>color.A<=.001,"highlights"=>color.A>.001&&luminance>=.65,"shadows"=>color.A>.001&&luminance<=.35,"similar"=>color.A>.001&&new Vector3(color.R-reference.R,color.G-reference.G,color.B-reference.B).Length()<=threshold*1.732,_=>false};if(chosen)mask.SetPixel(x,y,Colors.White);}commit_selection_bitmap(owner,mask);owner.Get("status").As<Label>().Text="Smart selection created";
    }
    public void complete_selection_to_layer(Control owner,Image? bitmap)
    {
        if(bitmap==null||bitmap.IsEmpty()){owner.Get("status").As<Label>().Text="Could not read the canvas.";return;}var canvas=Canvas(owner);var sampler=new ImageCanvasSelectionOperations.SelectionSampler(canvas);for(int y=0;y<bitmap.GetHeight();y++)for(int x=0;x<bitmap.GetWidth();x++){var pixel=bitmap.GetPixel(x,y);pixel.A*=(float)sampler.Coverage(new Vector2(x,y));bitmap.SetPixel(x,y,pixel);}var document=Document(owner);var layer=_layers.create("image",document.Get("canvas_size").AsVector2I());layer.Set("label","Selection");var texture=ImageTexture.CreateFromImage(bitmap);layer.Set("texture",texture);layer.Set("paint_base",texture);Action(owner,()=>{document.Get("layers").AsGodotArray().Add(layer);var selected=canvas.Get("selected").AsGodotArray();selected.Clear();selected.Add(layer.Get("id"));});_canvas.clear_selection(canvas);
    }

